begin;
insert into public.ai_runs(trace_id,surface,status,duration_ms,model,prompt_version,created_at) values
('00000000-0000-4000-8000-000000000105','concierge','completed',10,'fixture','test-v1',now()),
('00000000-0000-4000-8000-000000000106','operations','completed',20,'fixture','test-v1',now()-interval '31 days');
insert into public.ai_feedback(trace_id,rating) values
('00000000-0000-4000-8000-000000000105','helpful'),
('00000000-0000-4000-8000-000000000106','not-helpful');
do $check$
declare r text; t text; op text;
begin
foreach r in array array['anon','authenticated'] loop
foreach t in array array['ai_runs','ai_feedback','ai_rate_buckets'] loop
foreach op in array array['INSERT','UPDATE','DELETE'] loop
if has_table_privilege(r,'public.'||t,op) then raise exception 'Unexpected client write grant'; end if;
end loop;
end loop;
if has_table_privilege(r,'public.ai_rate_buckets','SELECT') then raise exception 'Client bucket read allowed'; end if;
if has_function_privilege(r,'public.consume_ai_rate_limit(text,integer,integer)','EXECUTE') or has_function_privilege(r,'public.cleanup_ai_observability()','EXECUTE') then raise exception 'Client server-only RPC allowed'; end if;
end loop;
if has_table_privilege('anon','public.ai_runs','SELECT') or has_table_privilege('anon','public.ai_feedback','SELECT') then raise exception 'Anon telemetry read allowed'; end if;
end $check$;
set local role authenticated;
do $check$
declare role_value text;
begin
foreach role_value in array array['ordinary','staff'] loop
perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','app_metadata',jsonb_build_object('role',role_value),'user_metadata',jsonb_build_object('role','admin'))::text,true);
if exists(select 1 from public.ai_runs where trace_id in ('00000000-0000-4000-8000-000000000105','00000000-0000-4000-8000-000000000106')) or exists(select 1 from public.ai_feedback where trace_id='00000000-0000-4000-8000-000000000105') then raise exception 'Non-admin telemetry leak'; end if;
end loop;
perform set_config('request.jwt.claims','{"role":"authenticated","app_metadata":{"role":"admin"}}',true);
if (select count(*) from public.ai_runs where trace_id in ('00000000-0000-4000-8000-000000000105','00000000-0000-4000-8000-000000000106')) <> 2 or (select count(*) from public.ai_feedback where trace_id='00000000-0000-4000-8000-000000000105') <> 1 then raise exception 'Admin telemetry read denied'; end if;
end $check$;
reset role;
set local role service_role;
insert into public.ai_runs(trace_id,surface,status,duration_ms,model,prompt_version) values ('00000000-0000-4000-8000-000000000107','booking-insight','failed',1,'fixture','test-v1');
update public.ai_runs set duration_ms=2 where trace_id='00000000-0000-4000-8000-000000000107';
delete from public.ai_runs where trace_id='00000000-0000-4000-8000-000000000107';
update public.ai_feedback set rating='not-helpful' where trace_id='00000000-0000-4000-8000-000000000105';
do $check$
declare rejected boolean; test_args jsonb;
begin
foreach test_args in array array['{"bucket":"","limit":1,"window":60}'::jsonb,'{"bucket":"feature05-boundary","limit":null,"window":60}'::jsonb,'{"bucket":"feature05-boundary","limit":1,"window":null}'::jsonb,'{"bucket":"feature05-boundary","limit":0,"window":60}'::jsonb] loop
rejected := false;
begin perform public.consume_ai_rate_limit(test_args->>'bucket',(test_args->>'limit')::int,(test_args->>'window')::int); exception when raise_exception then rejected := true; end;
if not rejected then raise exception 'Invalid parameters accepted'; end if;
end loop;
if not (public.consume_ai_rate_limit('feature05-window-probe',1,60)->>'allowed')::boolean then raise exception 'First window consume denied'; end if;
if (public.consume_ai_rate_limit('feature05-window-probe',1,60)->>'allowed')::boolean then raise exception 'Quota exceeded'; end if;
update public.ai_rate_buckets set window_start=now()-interval '2 minutes' where bucket='feature05-window-probe';
if not (public.consume_ai_rate_limit('feature05-window-probe',1,60)->>'allowed')::boolean then raise exception 'Window failed to reset'; end if;
perform public.cleanup_ai_observability();
if exists(select 1 from public.ai_runs where trace_id='00000000-0000-4000-8000-000000000106') or exists(select 1 from public.ai_feedback where trace_id='00000000-0000-4000-8000-000000000106') then raise exception 'Retention/cascade failed'; end if;
if not exists(select 1 from public.ai_runs where trace_id='00000000-0000-4000-8000-000000000105') then raise exception 'Retention removed current run'; end if;
end $check$;
rollback;
select 'extended grants/RLS/service CRUD/null boundary/window reset/retention cascade passed and rolled back' as result;
